package com.mewcode.plan;

import com.mewcode.tool.Tool;import com.mewcode.tool.ToolCategory;import com.mewcode.tool.ToolResult;import java.time.Instant;import java.util.ArrayList;import java.util.List;import java.util.Map;
public final class PlanTools {
 private PlanTools(){}
 public static final class Create implements Tool {private final PlanCoordinator c;public Create(PlanCoordinator c){this.c=c;}public String name(){return "CreatePlan";}public String description(){return "Create a structured execution plan with acceptance criteria.";}public ToolCategory category(){return ToolCategory.WRITE;}public boolean shouldDefer(){return true;}public Map<String,Object> schema(){return Map.of("name",name(),"description",description(),"input_schema",Map.of("type","object","properties",Map.of("goal",Map.of("type","string"),"steps",Map.of("type","array")),"required",List.of("goal","steps")));}@SuppressWarnings("unchecked") public ToolResult execute(Map<String,Object>a){try{List<PlanState.Step> steps=new ArrayList<>();for(Object raw:(List<?>)a.get("steps")){Map<String,Object>m=(Map<String,Object>)raw;List<String>deps=(List<String>)m.getOrDefault("dependsOn",List.of());List<String>criteria=(List<String>)m.getOrDefault("acceptanceCriteria",List.of("Implementation works"));steps.add(new PlanState.Step(String.valueOf(m.get("id")),String.valueOf(m.get("description")),deps,criteria,Boolean.TRUE.equals(m.get("requiresVerification")),PlanState.StepStatus.PENDING,0,null));}return ToolResult.success("Created plan "+c.create(String.valueOf(a.get("goal")),steps).id());}catch(Exception e){return ToolResult.error(e.getMessage());}}}
 public static final class Complete implements Tool {private final PlanCoordinator c;public Complete(PlanCoordinator c){this.c=c;}public String name(){return "CompletePlanStep";}public String description(){return "Complete a plan step with verification evidence.";}public ToolCategory category(){return ToolCategory.WRITE;}public boolean shouldDefer(){return true;}public Map<String,Object> schema(){return Map.of("name",name(),"description",description(),"input_schema",Map.of("type","object","properties",Map.of("stepId",Map.of("type","string"),"verification",Map.of("type","array"),"changedFiles",Map.of("type","array")),"required",List.of("stepId")));}@SuppressWarnings("unchecked")public ToolResult execute(Map<String,Object>a){try{return ToolResult.success("Plan status: "+c.complete(String.valueOf(a.get("stepId")),(List<String>)a.getOrDefault("verification",List.of()),(List<String>)a.getOrDefault("changedFiles",List.of())).status());}catch(Exception e){return ToolResult.error(e.getMessage());}}}
 public static final class Fail implements Tool {private final PlanCoordinator c;public Fail(PlanCoordinator c){this.c=c;}public String name(){return "FailPlanStep";}public String description(){return "Record a failed plan attempt.";}public ToolCategory category(){return ToolCategory.WRITE;}public boolean shouldDefer(){return true;}public Map<String,Object> schema(){return Map.of("name",name(),"description",description(),"input_schema",Map.of("type","object","properties",Map.of("stepId",Map.of("type","string"),"reason",Map.of("type","string")),"required",List.of("stepId","reason")));}public ToolResult execute(Map<String,Object>a){try{return ToolResult.success("Plan status: "+c.fail(String.valueOf(a.get("stepId")),String.valueOf(a.get("reason"))).status());}catch(Exception e){return ToolResult.error(e.getMessage());}}}
}
